-- Abstimmung über Liedvorschläge (#391).
SET NAMES utf8mb4;

-- Der Statussatz nennt jetzt auch „Abgestimmt“. Weil der früheste Seed gewinnt
-- (ON DUPLICATE KEY UPDATE value = value), muss der alte einmal weg, sonst
-- bliebe in bestehenden Datenbanken ein Satz stehen, der den neuen Status
-- verschweigt.
DELETE FROM translations WHERE tkey = 'help_songs_2'
  AND (SELECT COUNT(*) FROM settings WHERE `key` = 'help_songs_2_v2') = 0;
  ON DUPLICATE KEY UPDATE value = value;


ON DUPLICATE KEY UPDATE value = value;
